"use client";

import { Button } from "./ui/button";
import React from "react";

export function Cta25_1() {
  return (
    <section className="px-[5%] py-16 md:py-24 lg:py-28">
      <div className="container max-w-lg text-center">
        <h2 className="heading-h2 mb-5 font-bold md:mb-6">Let's connect</h2>
        <p className="text-medium">
          Interested in collaboration or have a project in mind? Reach out
          anytime.
        </p>
        <div className="mt-6 flex items-center justify-center gap-4 md:mt-8">
          <Button title="Email">Email</Button>
          <Button title="Call" variant="secondary">
            Call
          </Button>
        </div>
      </div>
    </section>
  );
}
